Object.assign(SD["lru"], { codeTitle: "Build an LRU cache", codeNote: "A hash map plus a doubly linked list with sentinel nodes. Capacity 2, the same sequence as LeetCode 146.", codeOut: "get(1) = 1\nput(3): evicted 2\nget(2) = -1\nput(4): evicted 1\nget(1) = -1\nget(3) = 3\nget(4) = 4", code: {"python": "class Node:\n    def __init__(self, key=0, val=0):\n        self.key, self.val = key, val\n        self.prev = self.next = None\n\n\nclass LRUCache:\n    \"\"\"Hash map for O(1) lookup + doubly linked list for recency order.\"\"\"\n\n    def __init__(self, capacity):\n        self.cap = capacity\n        self.map = {}\n        self.head, self.tail = Node(), Node()      # sentinels\n        self.head.next, self.tail.prev = self.tail, self.head\n\n    def _unlink(self, n):\n        n.prev.next, n.next.prev = n.next, n.prev\n\n    def _push_front(self, n):                       # most recent goes first\n        n.prev, n.next = self.head, self.head.next\n        self.head.next.prev = n\n        self.head.next = n\n\n    def get(self, key):\n        n = self.map.get(key)\n        if n is None:\n            return -1\n        self._unlink(n)\n        self._push_front(n)\n        return n.val\n\n    def put(self, key, val):\n        \"\"\"Returns the evicted key, or None.\"\"\"\n        evicted = None\n        if key in self.map:\n            self._unlink(self.map[key])\n        elif len(self.map) == self.cap:\n            lru = self.tail.prev                    # least recently used\n            self._unlink(lru)\n            del self.map[lru.key]\n            evicted = lru.key\n        n = Node(key, val)\n        self.map[key] = n\n        self._push_front(n)\n        return evicted\n\n\nc = LRUCache(2)\nc.put(1, 1)\nc.put(2, 2)\nprint(\"get(1) =\", c.get(1))\nprint(\"put(3): evicted\", c.put(3, 3))\nprint(\"get(2) =\", c.get(2))\nprint(\"put(4): evicted\", c.put(4, 4))\nprint(\"get(1) =\", c.get(1))\nprint(\"get(3) =\", c.get(3))\nprint(\"get(4) =\", c.get(4))", "javascript": "class Node {\n  constructor(key = 0, val = 0) { this.key = key; this.val = val; this.prev = this.next = null; }\n}\n\n// Hash map for O(1) lookup + doubly linked list for recency order.\nclass LRUCache {\n  constructor(capacity) {\n    this.cap = capacity;\n    this.map = new Map();\n    this.head = new Node(); this.tail = new Node();   // sentinels\n    this.head.next = this.tail; this.tail.prev = this.head;\n  }\n  unlink(n) { n.prev.next = n.next; n.next.prev = n.prev; }\n  pushFront(n) {                                       // most recent goes first\n    n.prev = this.head; n.next = this.head.next;\n    this.head.next.prev = n; this.head.next = n;\n  }\n  get(key) {\n    const n = this.map.get(key);\n    if (!n) return -1;\n    this.unlink(n); this.pushFront(n);\n    return n.val;\n  }\n  put(key, val) {                                      // returns evicted key or null\n    let evicted = null;\n    if (this.map.has(key)) this.unlink(this.map.get(key));\n    else if (this.map.size === this.cap) {\n      const lru = this.tail.prev;                      // least recently used\n      this.unlink(lru); this.map.delete(lru.key); evicted = lru.key;\n    }\n    const n = new Node(key, val);\n    this.map.set(key, n); this.pushFront(n);\n    return evicted;\n  }\n}\n\nconst c = new LRUCache(2);\nc.put(1, 1);\nc.put(2, 2);\nconsole.log(\"get(1) =\", c.get(1));\nconsole.log(\"put(3): evicted\", c.put(3, 3));\nconsole.log(\"get(2) =\", c.get(2));\nconsole.log(\"put(4): evicted\", c.put(4, 4));\nconsole.log(\"get(1) =\", c.get(1));\nconsole.log(\"get(3) =\", c.get(3));\nconsole.log(\"get(4) =\", c.get(4));", "java": "import java.util.HashMap;\nimport java.util.Map;\n\npublic class Main {\n    static class Node {\n        int key, val; Node prev, next;\n        Node(int k, int v) { key = k; val = v; }\n    }\n\n    // Hash map for O(1) lookup + doubly linked list for recency order.\n    static class LRUCache {\n        private final int cap;\n        private final Map<Integer, Node> map = new HashMap<>();\n        private final Node head = new Node(0, 0), tail = new Node(0, 0);   // sentinels\n\n        LRUCache(int capacity) { cap = capacity; head.next = tail; tail.prev = head; }\n\n        private void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }\n        private void pushFront(Node n) {                                    // most recent first\n            n.prev = head; n.next = head.next;\n            head.next.prev = n; head.next = n;\n        }\n\n        int get(int key) {\n            Node n = map.get(key);\n            if (n == null) return -1;\n            unlink(n); pushFront(n);\n            return n.val;\n        }\n\n        Integer put(int key, int val) {                                     // returns evicted key or null\n            Integer evicted = null;\n            if (map.containsKey(key)) unlink(map.get(key));\n            else if (map.size() == cap) {\n                Node lru = tail.prev;                                       // least recently used\n                unlink(lru); map.remove(lru.key); evicted = lru.key;\n            }\n            Node n = new Node(key, val);\n            map.put(key, n); pushFront(n);\n            return evicted;\n        }\n    }\n\n    public static void main(String[] args) {\n        LRUCache c = new LRUCache(2);\n        c.put(1, 1);\n        c.put(2, 2);\n        System.out.println(\"get(1) = \" + c.get(1));\n        System.out.println(\"put(3): evicted \" + c.put(3, 3));\n        System.out.println(\"get(2) = \" + c.get(2));\n        System.out.println(\"put(4): evicted \" + c.put(4, 4));\n        System.out.println(\"get(1) = \" + c.get(1));\n        System.out.println(\"get(3) = \" + c.get(3));\n        System.out.println(\"get(4) = \" + c.get(4));\n    }\n}", "cpp": "#include <iostream>\n#include <unordered_map>\n\nstruct Node {\n    int key, val;\n    Node *prev = nullptr, *next = nullptr;\n    Node(int k = 0, int v = 0) : key(k), val(v) {}\n};\n\n// Hash map for O(1) lookup + doubly linked list for recency order.\nclass LRUCache {\n    int cap;\n    std::unordered_map<int, Node*> map;\n    Node head, tail;                                   // sentinels\n\n    void unlink(Node* n) { n->prev->next = n->next; n->next->prev = n->prev; }\n    void pushFront(Node* n) {                          // most recent goes first\n        n->prev = &head; n->next = head.next;\n        head.next->prev = n; head.next = n;\n    }\n\npublic:\n    explicit LRUCache(int capacity) : cap(capacity) { head.next = &tail; tail.prev = &head; }\n    ~LRUCache() { for (auto& kv : map) delete kv.second; }\n\n    int get(int key) {\n        auto it = map.find(key);\n        if (it == map.end()) return -1;\n        unlink(it->second); pushFront(it->second);\n        return it->second->val;\n    }\n\n    int put(int key, int val) {                        // returns evicted key, or -1\n        int evicted = -1;\n        auto it = map.find(key);\n        if (it != map.end()) { unlink(it->second); delete it->second; map.erase(it); }\n        else if ((int)map.size() == cap) {\n            Node* lru = tail.prev;                     // least recently used\n            unlink(lru); map.erase(lru->key); evicted = lru->key; delete lru;\n        }\n        Node* n = new Node(key, val);\n        map[key] = n; pushFront(n);\n        return evicted;\n    }\n};\n\nint main() {\n    LRUCache c(2);\n    c.put(1, 1);\n    c.put(2, 2);\n    std::cout << \"get(1) = \" << c.get(1) << \"\\n\";\n    std::cout << \"put(3): evicted \" << c.put(3, 3) << \"\\n\";\n    std::cout << \"get(2) = \" << c.get(2) << \"\\n\";\n    std::cout << \"put(4): evicted \" << c.put(4, 4) << \"\\n\";\n    std::cout << \"get(1) = \" << c.get(1) << \"\\n\";\n    std::cout << \"get(3) = \" << c.get(3) << \"\\n\";\n    std::cout << \"get(4) = \" << c.get(4) << \"\\n\";\n}"} });
Object.assign(SD["consistenthash"], { codeTitle: "Build a consistent-hash ring", codeNote: "3 servers \u00d7 100 virtual nodes, 10,000 keys. Adding a fourth server moves about a quarter of the keys; hash mod N would move about three quarters.", codeOut: "3 nodes: A=3612 B=3221 C=3167\n4 nodes: A=2840 B=2503 C=2216 D=2441\nmoved after adding D: 2441 of 10000 keys\nwith hash mod N, 3 -> 4 nodes moves: 7503", code: {"python": "import bisect\n\nM32 = 0xFFFFFFFF\n\n\ndef hash32(s):\n    \"\"\"FNV-1a, then a murmur3-style finalizer for better spread.\"\"\"\n    h = 2166136261\n    for b in s.encode():\n        h = ((h ^ b) * 16777619) & M32\n    h ^= h >> 16\n    h = (h * 0x85EBCA6B) & M32\n    h ^= h >> 13\n    h = (h * 0xC2B2AE35) & M32\n    h ^= h >> 16\n    return h\n\n\nclass Ring:\n    def __init__(self, vnodes=100):\n        self.vnodes = vnodes\n        self.points = []                    # sorted list of (position, node)\n\n    def add(self, node):\n        for i in range(self.vnodes):\n            bisect.insort(self.points, (hash32(f\"{node}#{i}\"), node))\n\n    def owner(self, key):\n        i = bisect.bisect_left(self.points, (hash32(key), \"\"))\n        return self.points[i % len(self.points)][1]   # wrap around the ring\n\n\ndef counts(ring, keys):\n    c = {}\n    for k in keys:\n        n = ring.owner(k)\n        c[n] = c.get(n, 0) + 1\n    return \" \".join(f\"{n}={c[n]}\" for n in sorted(c))\n\n\nkeys = [f\"key{i}\" for i in range(10000)]\nring = Ring()\nfor n in [\"A\", \"B\", \"C\"]:\n    ring.add(n)\nbefore = {k: ring.owner(k) for k in keys}\nprint(\"3 nodes:\", counts(ring, keys))\n\nring.add(\"D\")\nmoved = sum(1 for k in keys if ring.owner(k) != before[k])\nprint(\"4 nodes:\", counts(ring, keys))\nprint(f\"moved after adding D: {moved} of {len(keys)} keys\")\nprint(f\"with hash mod N, 3 -> 4 nodes moves: {sum(1 for k in keys if hash32(k) % 3 != hash32(k) % 4)}\")", "javascript": "// FNV-1a, then a murmur3-style finalizer for better spread.\nfunction hash32(s) {\n  let h = 2166136261;\n  for (const b of Buffer.from(s)) h = Math.imul(h ^ b, 16777619) >>> 0;\n  h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b) >>> 0;\n  h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35) >>> 0;\n  h ^= h >>> 16;\n  return h >>> 0;\n}\n\nclass Ring {\n  constructor(vnodes = 100) { this.vnodes = vnodes; this.points = []; }   // sorted [position, node]\n  add(node) {\n    for (let i = 0; i < this.vnodes; i++) this.points.push([hash32(`${node}#${i}`), node]);\n    this.points.sort((a, b) => a[0] - b[0] || (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));\n  }\n  owner(key) {\n    const h = hash32(key);\n    let lo = 0, hi = this.points.length;          // first position >= h\n    while (lo < hi) { const mid = (lo + hi) >> 1; if (this.points[mid][0] < h) lo = mid + 1; else hi = mid; }\n    return this.points[lo % this.points.length][1];   // wrap around the ring\n  }\n}\n\nfunction counts(ring, keys) {\n  const c = {};\n  for (const k of keys) { const n = ring.owner(k); c[n] = (c[n] || 0) + 1; }\n  return Object.keys(c).sort().map(n => `${n}=${c[n]}`).join(\" \");\n}\n\nconst keys = Array.from({ length: 10000 }, (_, i) => `key${i}`);\nconst ring = new Ring();\nfor (const n of [\"A\", \"B\", \"C\"]) ring.add(n);\nconst before = new Map(keys.map(k => [k, ring.owner(k)]));\nconsole.log(\"3 nodes:\", counts(ring, keys));\n\nring.add(\"D\");\nconst moved = keys.filter(k => ring.owner(k) !== before.get(k)).length;\nconsole.log(\"4 nodes:\", counts(ring, keys));\nconsole.log(`moved after adding D: ${moved} of ${keys.length} keys`);\nconsole.log(`with hash mod N, 3 -> 4 nodes moves: ${keys.filter(k => hash32(k) % 3 !== hash32(k) % 4).length}`);", "java": "import java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic class Main {\n    // FNV-1a, then a murmur3-style finalizer for better spread. Returns an unsigned 32-bit value.\n    static long hash32(String s) {\n        int h = 0x811C9DC5;\n        for (byte b : s.getBytes(StandardCharsets.UTF_8)) h = (h ^ (b & 0xFF)) * 16777619;\n        h ^= h >>> 16; h *= 0x85EBCA6B;\n        h ^= h >>> 13; h *= 0xC2B2AE35;\n        h ^= h >>> 16;\n        return h & 0xFFFFFFFFL;\n    }\n\n    static class Ring {\n        final int vnodes;\n        final TreeMap<Long, String> points = new TreeMap<>();   // position -> node, kept sorted\n        Ring(int vnodes) { this.vnodes = vnodes; }\n        void add(String node) {\n            for (int i = 0; i < vnodes; i++) {\n                long p = hash32(node + \"#\" + i);\n                points.merge(p, node, (a, b) -> a.compareTo(b) <= 0 ? a : b);   // tie: smaller name\n            }\n        }\n        String owner(String key) {\n            Map.Entry<Long, String> e = points.ceilingEntry(hash32(key));     // first position >= hash\n            return (e != null ? e : points.firstEntry()).getValue();          // wrap around the ring\n        }\n    }\n\n    static String counts(Ring ring, List<String> keys) {\n        TreeMap<String, Integer> c = new TreeMap<>();\n        for (String k : keys) c.merge(ring.owner(k), 1, Integer::sum);\n        StringBuilder sb = new StringBuilder();\n        for (var e : c.entrySet()) sb.append(sb.length() > 0 ? \" \" : \"\").append(e.getKey()).append('=').append(e.getValue());\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        List<String> keys = new ArrayList<>();\n        for (int i = 0; i < 10000; i++) keys.add(\"key\" + i);\n        Ring ring = new Ring(100);\n        for (String n : new String[]{\"A\", \"B\", \"C\"}) ring.add(n);\n        Map<String, String> before = new HashMap<>();\n        for (String k : keys) before.put(k, ring.owner(k));\n        System.out.println(\"3 nodes: \" + counts(ring, keys));\n\n        ring.add(\"D\");\n        int moved = 0;\n        for (String k : keys) if (!ring.owner(k).equals(before.get(k))) moved++;\n        System.out.println(\"4 nodes: \" + counts(ring, keys));\n        System.out.println(\"moved after adding D: \" + moved + \" of \" + keys.size() + \" keys\");\n        int modMoved = 0;\n        for (String k : keys) if (hash32(k) % 3 != hash32(k) % 4) modMoved++;\n        System.out.println(\"with hash mod N, 3 -> 4 nodes moves: \" + modMoved);\n    }\n}", "cpp": "#include <algorithm>\n#include <cstdint>\n#include <iostream>\n#include <map>\n#include <string>\n#include <unordered_map>\n#include <utility>\n#include <vector>\n\n// FNV-1a, then a murmur3-style finalizer for better spread.\nuint32_t hash32(const std::string& s) {\n    uint32_t h = 2166136261u;\n    for (unsigned char b : s) h = (h ^ b) * 16777619u;\n    h ^= h >> 16; h *= 0x85EBCA6Bu;\n    h ^= h >> 13; h *= 0xC2B2AE35u;\n    h ^= h >> 16;\n    return h;\n}\n\nclass Ring {\n    int vnodes;\n    std::vector<std::pair<uint32_t, std::string>> points;   // sorted (position, node)\npublic:\n    explicit Ring(int v = 100) : vnodes(v) {}\n    void add(const std::string& node) {\n        for (int i = 0; i < vnodes; i++) points.push_back({hash32(node + \"#\" + std::to_string(i)), node});\n        std::sort(points.begin(), points.end());\n    }\n    std::string owner(const std::string& key) const {\n        auto it = std::lower_bound(points.begin(), points.end(), std::make_pair(hash32(key), std::string()));\n        if (it == points.end()) it = points.begin();          // wrap around the ring\n        return it->second;\n    }\n};\n\nstd::string counts(const Ring& ring, const std::vector<std::string>& keys) {\n    std::map<std::string, int> c;\n    for (auto& k : keys) c[ring.owner(k)]++;\n    std::string out;\n    for (auto& [n, v] : c) out += (out.empty() ? \"\" : \" \") + n + \"=\" + std::to_string(v);\n    return out;\n}\n\nint main() {\n    std::vector<std::string> keys;\n    for (int i = 0; i < 10000; i++) keys.push_back(\"key\" + std::to_string(i));\n    Ring ring;\n    for (auto n : {\"A\", \"B\", \"C\"}) ring.add(n);\n    std::unordered_map<std::string, std::string> before;\n    for (auto& k : keys) before[k] = ring.owner(k);\n    std::cout << \"3 nodes: \" << counts(ring, keys) << \"\\n\";\n\n    ring.add(\"D\");\n    int moved = 0;\n    for (auto& k : keys) if (ring.owner(k) != before[k]) moved++;\n    std::cout << \"4 nodes: \" << counts(ring, keys) << \"\\n\";\n    std::cout << \"moved after adding D: \" << moved << \" of \" << keys.size() << \" keys\\n\";\n    int modMoved = 0;\n    for (auto& k : keys) if (hash32(k) % 3 != hash32(k) % 4) modMoved++;\n    std::cout << \"with hash mod N, 3 -> 4 nodes moves: \" << modMoved << \"\\n\";\n}"} });
Object.assign(SD["clocks"], { codeTitle: "Build vector clocks", codeNote: "Compare, merge and tick: detect that two cart updates are concurrent.", codeOut: "base    {A:1, B:1}\nphone   {A:2, B:1}\nlaptop  {A:1, B:2}\nbase vs phone:   before\nphone vs laptop: concurrent\nmerged  {A:3, B:2}\nphone vs merged: before", code: {"python": "def compare(a, b):\n    \"\"\"Return 'before', 'after', 'equal' or 'concurrent' for vector clocks a and b.\"\"\"\n    nodes = set(a) | set(b)\n    a_le_b = all(a.get(n, 0) <= b.get(n, 0) for n in nodes)\n    b_le_a = all(b.get(n, 0) <= a.get(n, 0) for n in nodes)\n    if a_le_b and b_le_a:\n        return \"equal\"\n    if a_le_b:\n        return \"before\"\n    if b_le_a:\n        return \"after\"\n    return \"concurrent\"\n\n\ndef merge(a, b):\n    return {n: max(a.get(n, 0), b.get(n, 0)) for n in set(a) | set(b)}\n\n\ndef tick(clock, node):\n    c = dict(clock)\n    c[node] = c.get(node, 0) + 1\n    return c\n\n\ndef show(c):\n    return \"{\" + \", \".join(f\"{n}:{c[n]}\" for n in sorted(c)) + \"}\"\n\n\nbase = {\"A\": 1, \"B\": 1}\nphone = tick(base, \"A\")         # update on replica A\nlaptop = tick(base, \"B\")        # concurrent update on replica B\nprint(\"base   \", show(base))\nprint(\"phone  \", show(phone))\nprint(\"laptop \", show(laptop))\nprint(\"base vs phone:  \", compare(base, phone))\nprint(\"phone vs laptop:\", compare(phone, laptop))\nmerged = tick(merge(phone, laptop), \"A\")   # resolve siblings, record the merge\nprint(\"merged \", show(merged))\nprint(\"phone vs merged:\", compare(phone, merged))", "javascript": "// Return 'before', 'after', 'equal' or 'concurrent' for vector clocks a and b.\nfunction compare(a, b) {\n  const nodes = new Set([...Object.keys(a), ...Object.keys(b)]);\n  let aLeB = true, bLeA = true;\n  for (const n of nodes) {\n    if ((a[n] || 0) > (b[n] || 0)) aLeB = false;\n    if ((b[n] || 0) > (a[n] || 0)) bLeA = false;\n  }\n  if (aLeB && bLeA) return \"equal\";\n  if (aLeB) return \"before\";\n  if (bLeA) return \"after\";\n  return \"concurrent\";\n}\n\nfunction merge(a, b) {\n  const out = {};\n  for (const n of new Set([...Object.keys(a), ...Object.keys(b)])) out[n] = Math.max(a[n] || 0, b[n] || 0);\n  return out;\n}\n\nfunction tick(clock, node) { return { ...clock, [node]: (clock[node] || 0) + 1 }; }\n\nconst show = c => \"{\" + Object.keys(c).sort().map(n => `${n}:${c[n]}`).join(\", \") + \"}\";\n\nconst base = { A: 1, B: 1 };\nconst phone = tick(base, \"A\");      // update on replica A\nconst laptop = tick(base, \"B\");     // concurrent update on replica B\nconsole.log(\"base   \", show(base));\nconsole.log(\"phone  \", show(phone));\nconsole.log(\"laptop \", show(laptop));\nconsole.log(\"base vs phone:  \", compare(base, phone));\nconsole.log(\"phone vs laptop:\", compare(phone, laptop));\nconst merged = tick(merge(phone, laptop), \"A\");   // resolve siblings, record the merge\nconsole.log(\"merged \", show(merged));\nconsole.log(\"phone vs merged:\", compare(phone, merged));", "java": "import java.util.*;\n\npublic class Main {\n    // Return \"before\", \"after\", \"equal\" or \"concurrent\" for vector clocks a and b.\n    static String compare(Map<String, Integer> a, Map<String, Integer> b) {\n        Set<String> nodes = new TreeSet<>(a.keySet()); nodes.addAll(b.keySet());\n        boolean aLeB = true, bLeA = true;\n        for (String n : nodes) {\n            int x = a.getOrDefault(n, 0), y = b.getOrDefault(n, 0);\n            if (x > y) aLeB = false;\n            if (y > x) bLeA = false;\n        }\n        if (aLeB && bLeA) return \"equal\";\n        if (aLeB) return \"before\";\n        if (bLeA) return \"after\";\n        return \"concurrent\";\n    }\n\n    static Map<String, Integer> merge(Map<String, Integer> a, Map<String, Integer> b) {\n        Map<String, Integer> out = new TreeMap<>(a);\n        b.forEach((n, v) -> out.merge(n, v, Math::max));\n        return out;\n    }\n\n    static Map<String, Integer> tick(Map<String, Integer> clock, String node) {\n        Map<String, Integer> c = new TreeMap<>(clock);\n        c.merge(node, 1, Integer::sum);\n        return c;\n    }\n\n    static String show(Map<String, Integer> c) {\n        StringJoiner j = new StringJoiner(\", \", \"{\", \"}\");\n        new TreeMap<>(c).forEach((n, v) -> j.add(n + \":\" + v));\n        return j.toString();\n    }\n\n    public static void main(String[] args) {\n        Map<String, Integer> base = new TreeMap<>(Map.of(\"A\", 1, \"B\", 1));\n        Map<String, Integer> phone = tick(base, \"A\");     // update on replica A\n        Map<String, Integer> laptop = tick(base, \"B\");    // concurrent update on replica B\n        System.out.println(\"base    \" + show(base));\n        System.out.println(\"phone   \" + show(phone));\n        System.out.println(\"laptop  \" + show(laptop));\n        System.out.println(\"base vs phone:   \" + compare(base, phone));\n        System.out.println(\"phone vs laptop: \" + compare(phone, laptop));\n        Map<String, Integer> merged = tick(merge(phone, laptop), \"A\");   // resolve siblings\n        System.out.println(\"merged  \" + show(merged));\n        System.out.println(\"phone vs merged: \" + compare(phone, merged));\n    }\n}", "cpp": "#include <algorithm>\n#include <iostream>\n#include <map>\n#include <set>\n#include <string>\n\nusing Clock = std::map<std::string, int>;\n\nint at(const Clock& c, const std::string& n) { auto it = c.find(n); return it == c.end() ? 0 : it->second; }\n\n// Return \"before\", \"after\", \"equal\" or \"concurrent\" for vector clocks a and b.\nstd::string compare(const Clock& a, const Clock& b) {\n    std::set<std::string> nodes;\n    for (auto& [n, v] : a) nodes.insert(n);\n    for (auto& [n, v] : b) nodes.insert(n);\n    bool aLeB = true, bLeA = true;\n    for (auto& n : nodes) {\n        if (at(a, n) > at(b, n)) aLeB = false;\n        if (at(b, n) > at(a, n)) bLeA = false;\n    }\n    if (aLeB && bLeA) return \"equal\";\n    if (aLeB) return \"before\";\n    if (bLeA) return \"after\";\n    return \"concurrent\";\n}\n\nClock merge(const Clock& a, const Clock& b) {\n    Clock out = a;\n    for (auto& [n, v] : b) out[n] = std::max(at(out, n), v);\n    return out;\n}\n\nClock tick(Clock c, const std::string& node) { c[node]++; return c; }\n\nstd::string show(const Clock& c) {\n    std::string s = \"{\";\n    for (auto& [n, v] : c) s += (s.size() > 1 ? \", \" : \"\") + n + \":\" + std::to_string(v);\n    return s + \"}\";\n}\n\nint main() {\n    Clock base{{\"A\", 1}, {\"B\", 1}};\n    Clock phone = tick(base, \"A\");     // update on replica A\n    Clock laptop = tick(base, \"B\");    // concurrent update on replica B\n    std::cout << \"base    \" << show(base) << \"\\n\";\n    std::cout << \"phone   \" << show(phone) << \"\\n\";\n    std::cout << \"laptop  \" << show(laptop) << \"\\n\";\n    std::cout << \"base vs phone:   \" << compare(base, phone) << \"\\n\";\n    std::cout << \"phone vs laptop: \" << compare(phone, laptop) << \"\\n\";\n    Clock merged = tick(merge(phone, laptop), \"A\");   // resolve siblings, record the merge\n    std::cout << \"merged  \" << show(merged) << \"\\n\";\n    std::cout << \"phone vs merged: \" << compare(phone, merged) << \"\\n\";\n}"} });
Object.assign(SD["idgen"], { codeTitle: "Build a Snowflake ID generator", codeNote: "A fake clock makes the output reproducible, including the refusal when the clock moves backwards.", codeOut: "id=4194332672  ts=1000 machine=7 seq=0\nid=4194332673  ts=1000 machine=7 seq=1\nid=4194332674  ts=1000 machine=7 seq=2\nid=4198526976  ts=1001 machine=7 seq=0\nerror: clock moved backwards (999 < 1001); refusing", code: {"python": "EPOCH_BITS, MACHINE_BITS, SEQ_BITS = 41, 10, 12\nMAX_SEQ = (1 << SEQ_BITS) - 1\n\n\nclass Snowflake:\n    \"\"\"64-bit IDs: 41-bit ms timestamp | 10-bit machine | 12-bit sequence.\"\"\"\n\n    def __init__(self, machine_id, clock):\n        assert 0 <= machine_id < (1 << MACHINE_BITS)\n        self.machine, self.clock = machine_id, clock   # clock() returns ms since custom epoch\n        self.last_ts, self.seq = -1, 0\n\n    def next_id(self):\n        ts = self.clock()\n        if ts < self.last_ts:\n            raise RuntimeError(f\"clock moved backwards ({ts} < {self.last_ts}); refusing\")\n        if ts == self.last_ts:\n            self.seq = (self.seq + 1) & MAX_SEQ\n            if self.seq == 0:                              # 4,096 IDs used this ms: wait\n                while ts <= self.last_ts:\n                    ts = self.clock()\n        else:\n            self.seq = 0\n        self.last_ts = ts\n        return (ts << (MACHINE_BITS + SEQ_BITS)) | (self.machine << SEQ_BITS) | self.seq\n\n\ndef decode(i):\n    return i >> 22, (i >> 12) & 0x3FF, i & 0xFFF\n\n\n# A fake clock so the output is reproducible: three IDs in ms 1000, one in 1001, then a jump back.\nticks = iter([1000, 1000, 1000, 1001, 999])\ngen = Snowflake(7, lambda: next(ticks))\nfor _ in range(4):\n    i = gen.next_id()\n    ts, m, s = decode(i)\n    print(f\"id={i}  ts={ts} machine={m} seq={s}\")\ntry:\n    gen.next_id()\nexcept RuntimeError as e:\n    print(\"error:\", e)", "javascript": "const MACHINE_BITS = 10n, SEQ_BITS = 12n, MAX_SEQ = (1n << SEQ_BITS) - 1n;\n\n// 64-bit IDs: 41-bit ms timestamp | 10-bit machine | 12-bit sequence. BigInt keeps all 64 bits exact.\nclass Snowflake {\n  constructor(machineId, clock) {          // clock() returns ms since custom epoch\n    this.machine = BigInt(machineId); this.clock = clock;\n    this.lastTs = -1n; this.seq = 0n;\n  }\n  nextId() {\n    let ts = BigInt(this.clock());\n    if (ts < this.lastTs) throw new Error(`clock moved backwards (${ts} < ${this.lastTs}); refusing`);\n    if (ts === this.lastTs) {\n      this.seq = (this.seq + 1n) & MAX_SEQ;\n      if (this.seq === 0n) while (ts <= this.lastTs) ts = BigInt(this.clock());   // 4,096 used: wait\n    } else this.seq = 0n;\n    this.lastTs = ts;\n    return (ts << (MACHINE_BITS + SEQ_BITS)) | (this.machine << SEQ_BITS) | this.seq;\n  }\n}\n\nconst decode = i => [i >> 22n, (i >> 12n) & 0x3FFn, i & 0xFFFn];\n\n// A fake clock so the output is reproducible: three IDs in ms 1000, one in 1001, then a jump back.\nconst ticks = [1000, 1000, 1000, 1001, 999][Symbol.iterator]();\nconst gen = new Snowflake(7, () => ticks.next().value);\nfor (let k = 0; k < 4; k++) {\n  const i = gen.nextId();\n  const [ts, m, s] = decode(i);\n  console.log(`id=${i}  ts=${ts} machine=${m} seq=${s}`);\n}\ntry { gen.nextId(); } catch (e) { console.log(\"error:\", e.message); }", "java": "import java.util.Iterator;\nimport java.util.List;\nimport java.util.function.LongSupplier;\n\npublic class Main {\n    static final int MACHINE_BITS = 10, SEQ_BITS = 12;\n    static final long MAX_SEQ = (1L << SEQ_BITS) - 1;\n\n    // 64-bit IDs: 41-bit ms timestamp | 10-bit machine | 12-bit sequence.\n    static class Snowflake {\n        final long machine; final LongSupplier clock;   // clock returns ms since custom epoch\n        long lastTs = -1, seq = 0;\n        Snowflake(long machineId, LongSupplier clock) { this.machine = machineId; this.clock = clock; }\n\n        synchronized long nextId() {\n            long ts = clock.getAsLong();\n            if (ts < lastTs) throw new IllegalStateException(\"clock moved backwards (\" + ts + \" < \" + lastTs + \"); refusing\");\n            if (ts == lastTs) {\n                seq = (seq + 1) & MAX_SEQ;\n                if (seq == 0) while (ts <= lastTs) ts = clock.getAsLong();   // 4,096 used: wait\n            } else seq = 0;\n            lastTs = ts;\n            return (ts << (MACHINE_BITS + SEQ_BITS)) | (machine << SEQ_BITS) | seq;\n        }\n    }\n\n    public static void main(String[] args) {\n        // A fake clock so the output is reproducible: three IDs in ms 1000, one in 1001, then a jump back.\n        Iterator<Long> ticks = List.of(1000L, 1000L, 1000L, 1001L, 999L).iterator();\n        Snowflake gen = new Snowflake(7, ticks::next);\n        for (int k = 0; k < 4; k++) {\n            long i = gen.nextId();\n            System.out.println(\"id=\" + i + \"  ts=\" + (i >> 22) + \" machine=\" + ((i >> 12) & 0x3FF) + \" seq=\" + (i & 0xFFF));\n        }\n        try { gen.nextId(); } catch (IllegalStateException e) { System.out.println(\"error: \" + e.getMessage()); }\n    }\n}", "cpp": "#include <cstdint>\n#include <functional>\n#include <iostream>\n#include <stdexcept>\n#include <string>\n#include <vector>\n\nconstexpr int MACHINE_BITS = 10, SEQ_BITS = 12;\nconstexpr uint64_t MAX_SEQ = (1ULL << SEQ_BITS) - 1;\n\n// 64-bit IDs: 41-bit ms timestamp | 10-bit machine | 12-bit sequence.\nclass Snowflake {\n    uint64_t machine;\n    std::function<int64_t()> clock;                // returns ms since custom epoch\n    int64_t lastTs = -1;\n    uint64_t seq = 0;\npublic:\n    Snowflake(uint64_t machineId, std::function<int64_t()> c) : machine(machineId), clock(std::move(c)) {}\n    uint64_t nextId() {\n        int64_t ts = clock();\n        if (ts < lastTs) throw std::runtime_error(\"clock moved backwards (\" + std::to_string(ts) + \" < \" + std::to_string(lastTs) + \"); refusing\");\n        if (ts == lastTs) {\n            seq = (seq + 1) & MAX_SEQ;\n            if (seq == 0) while (ts <= lastTs) ts = clock();   // 4,096 used: wait\n        } else seq = 0;\n        lastTs = ts;\n        return ((uint64_t)ts << (MACHINE_BITS + SEQ_BITS)) | (machine << SEQ_BITS) | seq;\n    }\n};\n\nint main() {\n    // A fake clock so the output is reproducible: three IDs in ms 1000, one in 1001, then a jump back.\n    std::vector<int64_t> ticks{1000, 1000, 1000, 1001, 999};\n    size_t t = 0;\n    Snowflake gen(7, [&] { return ticks[t++]; });\n    for (int k = 0; k < 4; k++) {\n        uint64_t i = gen.nextId();\n        std::cout << \"id=\" << i << \"  ts=\" << (i >> 22) << \" machine=\" << ((i >> 12) & 0x3FF) << \" seq=\" << (i & 0xFFF) << \"\\n\";\n    }\n    try { gen.nextId(); } catch (const std::runtime_error& e) { std::cout << \"error: \" << e.what() << \"\\n\"; }\n}"} });
Object.assign(SD["bloom"], { codeTitle: "Build a Bloom filter", codeNote: "Sized for 100 keys at a 1% false-positive rate, using double hashing to derive k positions from two hashes.", codeOut: "m = 959 bits, k = 7 hash functions\nbits set: 497 of 959\nmembers found: 100 / 100 (never a false negative)\nfalse positives: 106 / 10000 = 1.06%", code: {"python": "import math\n\nM32 = 0xFFFFFFFF\n\n\ndef fnv1a(s):\n    h = 2166136261\n    for b in s.encode():\n        h = ((h ^ b) * 16777619) & M32\n    return h\n\n\ndef mix(h):                                   # murmur3 finalizer\n    h ^= h >> 16\n    h = (h * 0x85EBCA6B) & M32\n    h ^= h >> 13\n    h = (h * 0xC2B2AE35) & M32\n    return h ^ (h >> 16)\n\n\nclass BloomFilter:\n    def __init__(self, n, p):\n        self.m = math.ceil(-n * math.log(p) / (math.log(2) ** 2))   # bits\n        self.k = round(self.m / n * math.log(2))                     # hash functions\n        self.bits = bytearray((self.m + 7) // 8)\n\n    def _positions(self, key):                # double hashing: h1 + i*h2\n        h1 = mix(fnv1a(key))\n        h2 = mix(h1) | 1\n        return [((h1 + i * h2) & M32) % self.m for i in range(self.k)]\n\n    def add(self, key):\n        for p in self._positions(key):\n            self.bits[p >> 3] |= 1 << (p & 7)\n\n    def might_contain(self, key):\n        return all(self.bits[p >> 3] & (1 << (p & 7)) for p in self._positions(key))\n\n\nbf = BloomFilter(n=100, p=0.01)\nprint(f\"m = {bf.m} bits, k = {bf.k} hash functions\")\nfor i in range(100):\n    bf.add(f\"user{i}\")\npresent = sum(bf.might_contain(f\"user{i}\") for i in range(100))\nfalse_pos = sum(bf.might_contain(f\"other{i}\") for i in range(10000))\nones = sum(bin(b).count(\"1\") for b in bf.bits)\nprint(f\"bits set: {ones} of {bf.m}\")\nprint(f\"members found: {present} / 100 (never a false negative)\")\nprint(f\"false positives: {false_pos} / 10000 = {false_pos / 100:.2f}%\")", "javascript": "function fnv1a(s) {\n  let h = 2166136261;\n  for (const b of Buffer.from(s)) h = Math.imul(h ^ b, 16777619) >>> 0;\n  return h;\n}\nfunction mix(h) {                              // murmur3 finalizer\n  h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b) >>> 0;\n  h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35) >>> 0;\n  return (h ^ (h >>> 16)) >>> 0;\n}\n\nclass BloomFilter {\n  constructor(n, p) {\n    this.m = Math.ceil(-n * Math.log(p) / (Math.log(2) ** 2));   // bits\n    this.k = Math.round(this.m / n * Math.log(2));               // hash functions\n    this.bits = new Uint8Array(Math.ceil(this.m / 8));\n  }\n  positions(key) {                             // double hashing: h1 + i*h2\n    const h1 = mix(fnv1a(key)), h2 = (mix(h1) | 1) >>> 0, out = [];\n    for (let i = 0; i < this.k; i++) out.push(((h1 + Math.imul(i, h2)) >>> 0) % this.m);\n    return out;\n  }\n  add(key) { for (const p of this.positions(key)) this.bits[p >> 3] |= 1 << (p & 7); }\n  mightContain(key) { return this.positions(key).every(p => this.bits[p >> 3] & (1 << (p & 7))); }\n}\n\nconst bf = new BloomFilter(100, 0.01);\nconsole.log(`m = ${bf.m} bits, k = ${bf.k} hash functions`);\nfor (let i = 0; i < 100; i++) bf.add(`user${i}`);\nlet present = 0, falsePos = 0, ones = 0;\nfor (let i = 0; i < 100; i++) if (bf.mightContain(`user${i}`)) present++;\nfor (let i = 0; i < 10000; i++) if (bf.mightContain(`other${i}`)) falsePos++;\nfor (const b of bf.bits) for (let x = b; x; x &= x - 1) ones++;\nconsole.log(`bits set: ${ones} of ${bf.m}`);\nconsole.log(`members found: ${present} / 100 (never a false negative)`);\nconsole.log(`false positives: ${falsePos} / 10000 = ${(falsePos / 100).toFixed(2)}%`);", "java": "import java.nio.charset.StandardCharsets;\n\npublic class Main {\n    static int fnv1a(String s) {\n        int h = 0x811C9DC5;\n        for (byte b : s.getBytes(StandardCharsets.UTF_8)) h = (h ^ (b & 0xFF)) * 16777619;\n        return h;\n    }\n    static int mix(int h) {                    // murmur3 finalizer\n        h ^= h >>> 16; h *= 0x85EBCA6B;\n        h ^= h >>> 13; h *= 0xC2B2AE35;\n        return h ^ (h >>> 16);\n    }\n\n    static class BloomFilter {\n        final int m, k; final byte[] bits;\n        BloomFilter(int n, double p) {\n            m = (int) Math.ceil(-n * Math.log(p) / (Math.log(2) * Math.log(2)));   // bits\n            k = (int) Math.round((double) m / n * Math.log(2));                  // hash functions\n            bits = new byte[(m + 7) / 8];\n        }\n        int[] positions(String key) {          // double hashing: h1 + i*h2\n            int h1 = mix(fnv1a(key)), h2 = mix(h1) | 1;\n            int[] out = new int[k];\n            for (int i = 0; i < k; i++) out[i] = (int) (((h1 + i * h2) & 0xFFFFFFFFL) % m);\n            return out;\n        }\n        void add(String key) { for (int p : positions(key)) bits[p >> 3] |= (byte) (1 << (p & 7)); }\n        boolean mightContain(String key) {\n            for (int p : positions(key)) if ((bits[p >> 3] & (1 << (p & 7))) == 0) return false;\n            return true;\n        }\n    }\n\n    public static void main(String[] args) {\n        BloomFilter bf = new BloomFilter(100, 0.01);\n        System.out.println(\"m = \" + bf.m + \" bits, k = \" + bf.k + \" hash functions\");\n        for (int i = 0; i < 100; i++) bf.add(\"user\" + i);\n        int present = 0, falsePos = 0, ones = 0;\n        for (int i = 0; i < 100; i++) if (bf.mightContain(\"user\" + i)) present++;\n        for (int i = 0; i < 10000; i++) if (bf.mightContain(\"other\" + i)) falsePos++;\n        for (byte b : bf.bits) ones += Integer.bitCount(b & 0xFF);\n        System.out.println(\"bits set: \" + ones + \" of \" + bf.m);\n        System.out.println(\"members found: \" + present + \" / 100 (never a false negative)\");\n        System.out.printf(\"false positives: %d / 10000 = %.2f%%%n\", falsePos, falsePos / 100.0);\n    }\n}", "cpp": "#include <bitset>\n#include <cmath>\n#include <cstdint>\n#include <cstdio>\n#include <string>\n#include <vector>\n\nuint32_t fnv1a(const std::string& s) {\n    uint32_t h = 2166136261u;\n    for (unsigned char b : s) h = (h ^ b) * 16777619u;\n    return h;\n}\nuint32_t mix(uint32_t h) {                    // murmur3 finalizer\n    h ^= h >> 16; h *= 0x85EBCA6Bu;\n    h ^= h >> 13; h *= 0xC2B2AE35u;\n    return h ^ (h >> 16);\n}\n\nclass BloomFilter {\npublic:\n    uint32_t m, k;\n    std::vector<uint8_t> bits;\n    BloomFilter(int n, double p) {\n        m = (uint32_t)std::ceil(-n * std::log(p) / (std::log(2.0) * std::log(2.0)));   // bits\n        k = (uint32_t)std::llround((double)m / n * std::log(2.0));                     // hash functions\n        bits.assign((m + 7) / 8, 0);\n    }\n    std::vector<uint32_t> positions(const std::string& key) const {   // double hashing: h1 + i*h2\n        uint32_t h1 = mix(fnv1a(key)), h2 = mix(h1) | 1u;\n        std::vector<uint32_t> out;\n        for (uint32_t i = 0; i < k; i++) out.push_back((h1 + i * h2) % m);   // uint32 wraps mod 2^32\n        return out;\n    }\n    void add(const std::string& key) { for (auto p : positions(key)) bits[p >> 3] |= 1 << (p & 7); }\n    bool mightContain(const std::string& key) const {\n        for (auto p : positions(key)) if (!(bits[p >> 3] & (1 << (p & 7)))) return false;\n        return true;\n    }\n};\n\nint main() {\n    BloomFilter bf(100, 0.01);\n    std::printf(\"m = %u bits, k = %u hash functions\\n\", bf.m, bf.k);\n    for (int i = 0; i < 100; i++) bf.add(\"user\" + std::to_string(i));\n    int present = 0, falsePos = 0, ones = 0;\n    for (int i = 0; i < 100; i++) present += bf.mightContain(\"user\" + std::to_string(i));\n    for (int i = 0; i < 10000; i++) falsePos += bf.mightContain(\"other\" + std::to_string(i));\n    for (auto b : bf.bits) ones += std::bitset<8>(b).count();\n    std::printf(\"bits set: %d of %u\\n\", ones, bf.m);\n    std::printf(\"members found: %d / 100 (never a false negative)\\n\", present);\n    std::printf(\"false positives: %d / 10000 = %.2f%%\\n\", falsePos, falsePos / 100.0);\n}"} });
Object.assign(SD["sketches"], { codeTitle: "Build a count-min sketch", codeNote: "4 rows \u00d7 64 counters tracking 303 distinct items: frequent items are estimated closely and estimates never fall below the truth.", codeOut: "sketch: 4 x 64 = 256 counters for 303 distinct items\napple    true= 50  estimate= 52\nbanana   true= 30  estimate= 33\ncherry   true= 10  estimate= 16\nw7       true=  1  estimate=  6\nw123     true=  1  estimate=  4\nmissing  true=  0  estimate=  2", code: {"python": "M32 = 0xFFFFFFFF\n\n\ndef fnv1a(s):\n    h = 2166136261\n    for b in s.encode():\n        h = ((h ^ b) * 16777619) & M32\n    return h\n\n\ndef mix(h):                                   # murmur3 finalizer\n    h ^= h >> 16\n    h = (h * 0x85EBCA6B) & M32\n    h ^= h >> 13\n    h = (h * 0xC2B2AE35) & M32\n    return h ^ (h >> 16)\n\n\nclass CountMinSketch:\n    def __init__(self, depth, width):\n        self.d, self.w = depth, width\n        self.table = [[0] * width for _ in range(depth)]\n\n    def _col(self, key, row):                 # one independent-ish hash per row\n        return mix((fnv1a(key) + row * 0x9E3779B9) & M32) % self.w\n\n    def add(self, key, count=1):\n        for r in range(self.d):\n            self.table[r][self._col(key, r)] += count\n\n    def estimate(self, key):                  # min over rows: never below the true count\n        return min(self.table[r][self._col(key, r)] for r in range(self.d))\n\n\ncms = CountMinSketch(depth=4, width=64)\ntruth = {\"apple\": 50, \"banana\": 30, \"cherry\": 10}\nfor word, n in truth.items():\n    for _ in range(n):\n        cms.add(word)\nfor i in range(300):                          # 300 rare words, once each\n    cms.add(f\"w{i}\")\n    truth[f\"w{i}\"] = 1\n\nprint(f\"sketch: {cms.d} x {cms.w} = {cms.d * cms.w} counters for {len(truth)} distinct items\")\nfor word in [\"apple\", \"banana\", \"cherry\", \"w7\", \"w123\", \"missing\"]:\n    print(f\"{word:8} true={truth.get(word, 0):3}  estimate={cms.estimate(word):3}\")", "javascript": "function fnv1a(s) {\n  let h = 2166136261;\n  for (const b of Buffer.from(s)) h = Math.imul(h ^ b, 16777619) >>> 0;\n  return h;\n}\nfunction mix(h) {                              // murmur3 finalizer\n  h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b) >>> 0;\n  h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35) >>> 0;\n  return (h ^ (h >>> 16)) >>> 0;\n}\n\nclass CountMinSketch {\n  constructor(depth, width) {\n    this.d = depth; this.w = width;\n    this.table = Array.from({ length: depth }, () => new Array(width).fill(0));\n  }\n  col(key, row) { return mix((fnv1a(key) + Math.imul(row, 0x9e3779b9)) >>> 0) % this.w; }   // one hash per row\n  add(key, count = 1) { for (let r = 0; r < this.d; r++) this.table[r][this.col(key, r)] += count; }\n  estimate(key) {                              // min over rows: never below the true count\n    let m = Infinity;\n    for (let r = 0; r < this.d; r++) m = Math.min(m, this.table[r][this.col(key, r)]);\n    return m;\n  }\n}\n\nconst cms = new CountMinSketch(4, 64);\nconst truth = { apple: 50, banana: 30, cherry: 10 };\nfor (const [word, n] of Object.entries(truth)) for (let i = 0; i < n; i++) cms.add(word);\nfor (let i = 0; i < 300; i++) { cms.add(`w${i}`); truth[`w${i}`] = 1; }   // 300 rare words, once each\n\nconsole.log(`sketch: ${cms.d} x ${cms.w} = ${cms.d * cms.w} counters for ${Object.keys(truth).length} distinct items`);\nfor (const word of [\"apple\", \"banana\", \"cherry\", \"w7\", \"w123\", \"missing\"])\n  console.log(`${word.padEnd(8)} true=${String(truth[word] || 0).padStart(3)}  estimate=${String(cms.estimate(word)).padStart(3)}`);", "java": "import java.nio.charset.StandardCharsets;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\n\npublic class Main {\n    static int fnv1a(String s) {\n        int h = 0x811C9DC5;\n        for (byte b : s.getBytes(StandardCharsets.UTF_8)) h = (h ^ (b & 0xFF)) * 16777619;\n        return h;\n    }\n    static int mix(int h) {                    // murmur3 finalizer\n        h ^= h >>> 16; h *= 0x85EBCA6B;\n        h ^= h >>> 13; h *= 0xC2B2AE35;\n        return h ^ (h >>> 16);\n    }\n\n    static class CountMinSketch {\n        final int d, w; final long[][] table;\n        CountMinSketch(int depth, int width) { d = depth; w = width; table = new long[depth][width]; }\n        int col(String key, int row) {         // one hash per row\n            return (int) ((mix(fnv1a(key) + row * 0x9E3779B9) & 0xFFFFFFFFL) % w);\n        }\n        void add(String key) { for (int r = 0; r < d; r++) table[r][col(key, r)]++; }\n        long estimate(String key) {            // min over rows: never below the true count\n            long m = Long.MAX_VALUE;\n            for (int r = 0; r < d; r++) m = Math.min(m, table[r][col(key, r)]);\n            return m;\n        }\n    }\n\n    public static void main(String[] args) {\n        CountMinSketch cms = new CountMinSketch(4, 64);\n        Map<String, Integer> truth = new LinkedHashMap<>(Map.of(\"apple\", 50, \"banana\", 30, \"cherry\", 10));\n        for (var e : truth.entrySet()) for (int i = 0; i < e.getValue(); i++) cms.add(e.getKey());\n        for (int i = 0; i < 300; i++) { cms.add(\"w\" + i); truth.put(\"w\" + i, 1); }   // 300 rare words\n\n        System.out.println(\"sketch: \" + cms.d + \" x \" + cms.w + \" = \" + cms.d * cms.w + \" counters for \" + truth.size() + \" distinct items\");\n        for (String word : new String[]{\"apple\", \"banana\", \"cherry\", \"w7\", \"w123\", \"missing\"})\n            System.out.printf(\"%-8s true=%3d  estimate=%3d%n\", word, truth.getOrDefault(word, 0), cms.estimate(word));\n    }\n}", "cpp": "#include <algorithm>\n#include <climits>\n#include <cstdint>\n#include <cstdio>\n#include <map>\n#include <string>\n#include <vector>\n\nuint32_t fnv1a(const std::string& s) {\n    uint32_t h = 2166136261u;\n    for (unsigned char b : s) h = (h ^ b) * 16777619u;\n    return h;\n}\nuint32_t mix(uint32_t h) {                    // murmur3 finalizer\n    h ^= h >> 16; h *= 0x85EBCA6Bu;\n    h ^= h >> 13; h *= 0xC2B2AE35u;\n    return h ^ (h >> 16);\n}\n\nclass CountMinSketch {\npublic:\n    int d, w;\n    std::vector<std::vector<long>> table;\n    CountMinSketch(int depth, int width) : d(depth), w(width), table(depth, std::vector<long>(width, 0)) {}\n    int col(const std::string& key, uint32_t row) const { return mix(fnv1a(key) + row * 0x9E3779B9u) % w; }   // one hash per row\n    void add(const std::string& key) { for (int r = 0; r < d; r++) table[r][col(key, r)]++; }\n    long estimate(const std::string& key) const {   // min over rows: never below the true count\n        long m = LONG_MAX;\n        for (int r = 0; r < d; r++) m = std::min(m, table[r][col(key, r)]);\n        return m;\n    }\n};\n\nint main() {\n    CountMinSketch cms(4, 64);\n    std::map<std::string, int> truth{{\"apple\", 50}, {\"banana\", 30}, {\"cherry\", 10}};\n    for (auto& [word, n] : truth) for (int i = 0; i < n; i++) cms.add(word);\n    for (int i = 0; i < 300; i++) { cms.add(\"w\" + std::to_string(i)); truth[\"w\" + std::to_string(i)] = 1; }\n\n    std::printf(\"sketch: %d x %d = %d counters for %zu distinct items\\n\", cms.d, cms.w, cms.d * cms.w, truth.size());\n    for (std::string word : {\"apple\", \"banana\", \"cherry\", \"w7\", \"w123\", \"missing\"})\n        std::printf(\"%-8s true=%3d  estimate=%3ld\\n\", word.c_str(), truth.count(word) ? truth[word] : 0, cms.estimate(word));\n}"} });
Object.assign(SD["ratelimit"], { codeTitle: "Build a token bucket", codeNote: "Burst of 5, refill 2 tokens per second, with simulated timestamps in milliseconds.", codeOut: "t=    0 ms  allowed         tokens left 4.0\nt=    0 ms  allowed         tokens left 3.0\nt=    0 ms  allowed         tokens left 2.0\nt=    0 ms  allowed         tokens left 1.0\nt=    0 ms  allowed         tokens left 0.0\nt=    0 ms  rejected (429)  tokens left 0.0\nt=    0 ms  rejected (429)  tokens left 0.0\nt=  250 ms  rejected (429)  tokens left 0.5\nt=  500 ms  allowed         tokens left 0.0\nt= 1000 ms  allowed         tokens left 0.0\nt= 1000 ms  rejected (429)  tokens left 0.0\nt= 1000 ms  rejected (429)  tokens left 0.0\nt= 4000 ms  allowed         tokens left 4.0\nt= 4000 ms  allowed         tokens left 3.0\nt= 4000 ms  allowed         tokens left 2.0\nt= 4000 ms  allowed         tokens left 1.0\nt= 4000 ms  allowed         tokens left 0.0\nt= 4000 ms  rejected (429)  tokens left 0.0\n12 of 18 allowed", code: {"python": "class TokenBucket:\n    \"\"\"Capacity `burst` tokens, refilled at `rate` tokens per second.\n    Tokens are kept in thousandths so the arithmetic is exact.\"\"\"\n\n    def __init__(self, burst, rate):\n        self.capacity = burst * 1000\n        self.rate = rate                       # tokens per second = milli-tokens per ms\n        self.tokens = self.capacity\n        self.last_ms = 0\n\n    def allow(self, now_ms):\n        elapsed = now_ms - self.last_ms\n        self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)\n        self.last_ms = now_ms\n        if self.tokens >= 1000:\n            self.tokens -= 1000\n            return True\n        return False\n\n\nbucket = TokenBucket(burst=5, rate=2)          # 5-request bursts, 2 requests/s sustained\nrequests = [0, 0, 0, 0, 0, 0, 0, 250, 500, 1000, 1000, 1000, 4000, 4000, 4000, 4000, 4000, 4000]\nallowed = 0\nfor t in requests:\n    ok = bucket.allow(t)\n    allowed += ok\n    status = \"allowed \" if ok else \"rejected (429)\"\n    print(f\"t={t:5} ms  {status:14}  tokens left {bucket.tokens / 1000:.1f}\")\nprint(f\"{allowed} of {len(requests)} allowed\")", "javascript": "// Capacity `burst` tokens, refilled at `rate` tokens per second.\n// Tokens are kept in thousandths so the arithmetic is exact.\nclass TokenBucket {\n  constructor(burst, rate) {\n    this.capacity = burst * 1000;\n    this.rate = rate;                          // tokens per second = milli-tokens per ms\n    this.tokens = this.capacity;\n    this.lastMs = 0;\n  }\n  allow(nowMs) {\n    const elapsed = nowMs - this.lastMs;\n    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.rate);\n    this.lastMs = nowMs;\n    if (this.tokens >= 1000) { this.tokens -= 1000; return true; }\n    return false;\n  }\n}\n\nconst bucket = new TokenBucket(5, 2);          // 5-request bursts, 2 requests/s sustained\nconst requests = [0, 0, 0, 0, 0, 0, 0, 250, 500, 1000, 1000, 1000, 4000, 4000, 4000, 4000, 4000, 4000];\nlet allowed = 0;\nfor (const t of requests) {\n  const ok = bucket.allow(t);\n  if (ok) allowed++;\n  const status = ok ? \"allowed \" : \"rejected (429)\";\n  console.log(`t=${String(t).padStart(5)} ms  ${status.padEnd(14)}  tokens left ${(bucket.tokens / 1000).toFixed(1)}`);\n}\nconsole.log(`${allowed} of ${requests.length} allowed`);", "java": "public class Main {\n    // Capacity `burst` tokens, refilled at `rate` tokens per second.\n    // Tokens are kept in thousandths so the arithmetic is exact.\n    static class TokenBucket {\n        final long capacity, rate;             // rate: tokens per second = milli-tokens per ms\n        long tokens, lastMs = 0;\n        TokenBucket(long burst, long rate) { capacity = burst * 1000; this.rate = rate; tokens = capacity; }\n\n        synchronized boolean allow(long nowMs) {\n            long elapsed = nowMs - lastMs;\n            tokens = Math.min(capacity, tokens + elapsed * rate);\n            lastMs = nowMs;\n            if (tokens >= 1000) { tokens -= 1000; return true; }\n            return false;\n        }\n    }\n\n    public static void main(String[] args) {\n        TokenBucket bucket = new TokenBucket(5, 2);   // 5-request bursts, 2 requests/s sustained\n        long[] requests = {0, 0, 0, 0, 0, 0, 0, 250, 500, 1000, 1000, 1000, 4000, 4000, 4000, 4000, 4000, 4000};\n        int allowed = 0;\n        for (long t : requests) {\n            boolean ok = bucket.allow(t);\n            if (ok) allowed++;\n            System.out.printf(\"t=%5d ms  %-14s  tokens left %.1f%n\", t, ok ? \"allowed \" : \"rejected (429)\", bucket.tokens / 1000.0);\n        }\n        System.out.println(allowed + \" of \" + requests.length + \" allowed\");\n    }\n}", "cpp": "#include <algorithm>\n#include <cstdio>\n#include <vector>\n\n// Capacity `burst` tokens, refilled at `rate` tokens per second.\n// Tokens are kept in thousandths so the arithmetic is exact.\nclass TokenBucket {\npublic:\n    long capacity, rate, tokens, lastMs = 0;   // rate: tokens per second = milli-tokens per ms\n    TokenBucket(long burst, long r) : capacity(burst * 1000), rate(r), tokens(burst * 1000) {}\n    bool allow(long nowMs) {\n        long elapsed = nowMs - lastMs;\n        tokens = std::min(capacity, tokens + elapsed * rate);\n        lastMs = nowMs;\n        if (tokens >= 1000) { tokens -= 1000; return true; }\n        return false;\n    }\n};\n\nint main() {\n    TokenBucket bucket(5, 2);                  // 5-request bursts, 2 requests/s sustained\n    std::vector<long> requests{0, 0, 0, 0, 0, 0, 0, 250, 500, 1000, 1000, 1000, 4000, 4000, 4000, 4000, 4000, 4000};\n    int allowed = 0;\n    for (long t : requests) {\n        bool ok = bucket.allow(t);\n        allowed += ok;\n        std::printf(\"t=%5ld ms  %-14s  tokens left %.1f\\n\", t, ok ? \"allowed \" : \"rejected (429)\", bucket.tokens / 1000.0);\n    }\n    std::printf(\"%d of %zu allowed\\n\", allowed, requests.size());\n}"} });
Object.assign(SD["retries"], { codeTitle: "Retry with exponential backoff and full jitter", codeNote: "A tiny seeded PRNG makes the jitter identical in every language; in real code use the standard random generator.", codeOut: "attempt 1: 503 Service Unavailable; sleep 29 ms (max 100)\nattempt 2: 503 Service Unavailable; sleep 196 ms (max 200)\nattempt 3: 503 Service Unavailable; sleep 107 ms (max 400)\nattempt 4: 200 OK after 332 ms of waiting\nbackoff ceilings: [100, 200, 400, 800, 1600, 2000, 2000, 2000]", code: {"python": "class XorShift32:\n    \"\"\"Tiny deterministic PRNG so every language prints the same jitter.\n    In production use your language's normal random generator.\"\"\"\n\n    def __init__(self, seed):\n        self.s = seed\n\n    def below(self, n):                        # integer in [0, n)\n        x = self.s\n        x ^= (x << 13) & 0xFFFFFFFF\n        x ^= x >> 17\n        x ^= (x << 5) & 0xFFFFFFFF\n        self.s = x\n        return x % n\n\n\nBASE_MS, CAP_MS, MAX_ATTEMPTS = 100, 2000, 6\n\n\ndef backoff(attempt, rng):\n    \"\"\"Full jitter: random wait between 0 and min(cap, base * 2^attempt).\"\"\"\n    ceiling = min(CAP_MS, BASE_MS * (2 ** attempt))\n    return ceiling, rng.below(ceiling + 1)\n\n\ndef call_with_retries(op, rng):\n    waited = 0\n    for attempt in range(MAX_ATTEMPTS):\n        ok, status = op(attempt)\n        if ok:\n            print(f\"attempt {attempt + 1}: {status} after {waited} ms of waiting\")\n            return True\n        ceiling, wait = backoff(attempt, rng)\n        print(f\"attempt {attempt + 1}: {status}; sleep {wait} ms (max {ceiling})\")\n        waited += wait                         # real code: time.sleep(wait / 1000)\n    print(\"giving up: use fallback\")\n    return False\n\n\nrng = XorShift32(2463534242)\nflaky = lambda attempt: (attempt >= 3, \"200 OK\" if attempt >= 3 else \"503 Service Unavailable\")\ncall_with_retries(flaky, rng)\nprint(\"backoff ceilings:\", [min(CAP_MS, BASE_MS * 2 ** a) for a in range(8)])", "javascript": "// Tiny deterministic PRNG so every language prints the same jitter.\n// In production use Math.random() (or crypto) instead.\nclass XorShift32 {\n  constructor(seed) { this.s = seed >>> 0; }\n  below(n) {                                   // integer in [0, n)\n    let x = this.s;\n    x = (x ^ (x << 13)) >>> 0;\n    x = (x ^ (x >>> 17)) >>> 0;\n    x = (x ^ (x << 5)) >>> 0;\n    this.s = x;\n    return x % n;\n  }\n}\n\nconst BASE_MS = 100, CAP_MS = 2000, MAX_ATTEMPTS = 6;\n\n// Full jitter: random wait between 0 and min(cap, base * 2^attempt).\nfunction backoff(attempt, rng) {\n  const ceiling = Math.min(CAP_MS, BASE_MS * 2 ** attempt);\n  return [ceiling, rng.below(ceiling + 1)];\n}\n\nfunction callWithRetries(op, rng) {\n  let waited = 0;\n  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {\n    const [ok, status] = op(attempt);\n    if (ok) { console.log(`attempt ${attempt + 1}: ${status} after ${waited} ms of waiting`); return true; }\n    const [ceiling, wait] = backoff(attempt, rng);\n    console.log(`attempt ${attempt + 1}: ${status}; sleep ${wait} ms (max ${ceiling})`);\n    waited += wait;                            // real code: await sleep(wait)\n  }\n  console.log(\"giving up: use fallback\");\n  return false;\n}\n\nconst rng = new XorShift32(2463534242);\nconst flaky = attempt => [attempt >= 3, attempt >= 3 ? \"200 OK\" : \"503 Service Unavailable\"];\ncallWithRetries(flaky, rng);\nconsole.log(\"backoff ceilings: [\" + Array.from({ length: 8 }, (_, a) => Math.min(CAP_MS, BASE_MS * 2 ** a)).join(\", \") + \"]\");", "java": "import java.util.function.IntFunction;\n\npublic class Main {\n    // Tiny deterministic PRNG so every language prints the same jitter.\n    // In production use ThreadLocalRandom instead.\n    static class XorShift32 {\n        int s;\n        XorShift32(long seed) { s = (int) seed; }\n        int below(int n) {                     // integer in [0, n)\n            int x = s;\n            x ^= x << 13; x ^= x >>> 17; x ^= x << 5;\n            s = x;\n            return (int) ((x & 0xFFFFFFFFL) % n);\n        }\n    }\n\n    static final int BASE_MS = 100, CAP_MS = 2000, MAX_ATTEMPTS = 6;\n\n    // Full jitter: random wait between 0 and min(cap, base * 2^attempt).\n    static int ceiling(int attempt) { return (int) Math.min(CAP_MS, (long) BASE_MS << attempt); }\n\n    record Result(boolean ok, String status) {}\n\n    static boolean callWithRetries(IntFunction<Result> op, XorShift32 rng) {\n        int waited = 0;\n        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {\n            Result r = op.apply(attempt);\n            if (r.ok()) { System.out.println(\"attempt \" + (attempt + 1) + \": \" + r.status() + \" after \" + waited + \" ms of waiting\"); return true; }\n            int c = ceiling(attempt), wait = rng.below(c + 1);\n            System.out.println(\"attempt \" + (attempt + 1) + \": \" + r.status() + \"; sleep \" + wait + \" ms (max \" + c + \")\");\n            waited += wait;                    // real code: Thread.sleep(wait)\n        }\n        System.out.println(\"giving up: use fallback\");\n        return false;\n    }\n\n    public static void main(String[] args) {\n        XorShift32 rng = new XorShift32(2463534242L);\n        callWithRetries(a -> new Result(a >= 3, a >= 3 ? \"200 OK\" : \"503 Service Unavailable\"), rng);\n        StringBuilder sb = new StringBuilder(\"backoff ceilings: [\");\n        for (int a = 0; a < 8; a++) sb.append(a > 0 ? \", \" : \"\").append(ceiling(a));\n        System.out.println(sb.append(\"]\"));\n    }\n}", "cpp": "#include <algorithm>\n#include <cstdint>\n#include <functional>\n#include <iostream>\n#include <string>\n#include <utility>\n\n// Tiny deterministic PRNG so every language prints the same jitter.\n// In production use <random> instead.\nstruct XorShift32 {\n    uint32_t s;\n    explicit XorShift32(uint32_t seed) : s(seed) {}\n    uint32_t below(uint32_t n) {               // integer in [0, n)\n        uint32_t x = s;\n        x ^= x << 13; x ^= x >> 17; x ^= x << 5;\n        s = x;\n        return x % n;\n    }\n};\n\nconstexpr int BASE_MS = 100, CAP_MS = 2000, MAX_ATTEMPTS = 6;\n\n// Full jitter: random wait between 0 and min(cap, base * 2^attempt).\nint ceiling(int attempt) { return (int)std::min<long long>(CAP_MS, (long long)BASE_MS << attempt); }\n\nbool callWithRetries(const std::function<std::pair<bool, std::string>(int)>& op, XorShift32& rng) {\n    int waited = 0;\n    for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {\n        auto [ok, status] = op(attempt);\n        if (ok) { std::cout << \"attempt \" << attempt + 1 << \": \" << status << \" after \" << waited << \" ms of waiting\\n\"; return true; }\n        int c = ceiling(attempt), wait = (int)rng.below(c + 1);\n        std::cout << \"attempt \" << attempt + 1 << \": \" << status << \"; sleep \" << wait << \" ms (max \" << c << \")\\n\";\n        waited += wait;                        // real code: std::this_thread::sleep_for(...)\n    }\n    std::cout << \"giving up: use fallback\\n\";\n    return false;\n}\n\nint main() {\n    XorShift32 rng(2463534242u);\n    callWithRetries([](int a) { return std::make_pair(a >= 3, std::string(a >= 3 ? \"200 OK\" : \"503 Service Unavailable\")); }, rng);\n    std::cout << \"backoff ceilings: [\";\n    for (int a = 0; a < 8; a++) std::cout << (a ? \", \" : \"\") << ceiling(a);\n    std::cout << \"]\\n\";\n}"} });
Object.assign(SD["circuitbreaker"], { codeTitle: "Build a circuit breaker", codeNote: "Opens after 3 consecutive failures, cools down for 30 s, then allows one trial call. The dependency is down from t = 10 s to t = 55 s.", codeOut: "t= 0s  ok\nt= 5s  ok\nt=10s  failed\nt=15s  failed\nt=20s  failed                    CLOSED -> OPEN\nt=25s  rejected fast (fallback)\nt=30s  rejected fast (fallback)\nt=35s  rejected fast (fallback)\nt=40s  rejected fast (fallback)\nt=45s  rejected fast (fallback)\nt=50s  trial call failed\nt=55s  rejected fast (fallback)\nt=60s  rejected fast (fallback)\nt=65s  rejected fast (fallback)\nt=70s  rejected fast (fallback)\nt=75s  rejected fast (fallback)\nt=80s  trial call ok             OPEN -> CLOSED", code: {"python": "class CircuitBreaker:\n    def __init__(self, threshold=3, cooldown=30):\n        self.threshold, self.cooldown = threshold, cooldown\n        self.state, self.failures, self.opened_at = \"CLOSED\", 0, 0\n\n    def call(self, now, op):\n        if self.state == \"OPEN\":\n            if now - self.opened_at < self.cooldown:\n                return \"rejected fast (fallback)\"\n            self.state = \"HALF_OPEN\"              # cooldown over: allow one trial call\n        trial = \"trial call \" if self.state == \"HALF_OPEN\" else \"\"\n        try:\n            op(now)\n        except IOError:\n            self.failures += 1\n            if self.state == \"HALF_OPEN\" or self.failures >= self.threshold:\n                self.state, self.opened_at = \"OPEN\", now\n            return trial + \"failed\"\n        self.state, self.failures = \"CLOSED\", 0    # success closes and resets\n        return trial + \"ok\"\n\n\ndef dependency(now):                           # down from t=10 s to t=55 s\n    if 10 <= now < 55:\n        raise IOError(\"503\")\n\n\ncb = CircuitBreaker()\nfor t in range(0, 85, 5):\n    before = cb.state\n    result = cb.call(t, dependency)\n    change = f\"  {before} -> {cb.state}\" if cb.state != before else \"\"\n    print(f\"t={t:2}s  {result:24}{change}\")", "javascript": "class CircuitBreaker {\n  constructor(threshold = 3, cooldown = 30) {\n    this.threshold = threshold; this.cooldown = cooldown;\n    this.state = \"CLOSED\"; this.failures = 0; this.openedAt = 0;\n  }\n  call(now, op) {\n    if (this.state === \"OPEN\") {\n      if (now - this.openedAt < this.cooldown) return \"rejected fast (fallback)\";\n      this.state = \"HALF_OPEN\";                // cooldown over: allow one trial call\n    }\n    const trial = this.state === \"HALF_OPEN\" ? \"trial call \" : \"\";\n    try { op(now); }\n    catch (e) {\n      this.failures++;\n      if (this.state === \"HALF_OPEN\" || this.failures >= this.threshold) { this.state = \"OPEN\"; this.openedAt = now; }\n      return trial + \"failed\";\n    }\n    this.state = \"CLOSED\"; this.failures = 0;  // success closes and resets\n    return trial + \"ok\";\n  }\n}\n\nfunction dependency(now) {                     // down from t=10 s to t=55 s\n  if (now >= 10 && now < 55) throw new Error(\"503\");\n}\n\nconst cb = new CircuitBreaker();\nfor (let t = 0; t < 85; t += 5) {\n  const before = cb.state;\n  const result = cb.call(t, dependency);\n  const change = cb.state !== before ? `  ${before} -> ${cb.state}` : \"\";\n  console.log(`t=${String(t).padStart(2)}s  ${result.padEnd(24)}${change}`);\n}", "java": "import java.io.IOException;\n\npublic class Main {\n    interface Op { void run(int now) throws IOException; }\n\n    static class CircuitBreaker {\n        final int threshold, cooldown;\n        String state = \"CLOSED\"; int failures = 0, openedAt = 0;\n        CircuitBreaker(int threshold, int cooldown) { this.threshold = threshold; this.cooldown = cooldown; }\n\n        synchronized String call(int now, Op op) {\n            if (state.equals(\"OPEN\")) {\n                if (now - openedAt < cooldown) return \"rejected fast (fallback)\";\n                state = \"HALF_OPEN\";                       // cooldown over: allow one trial call\n            }\n            String trial = state.equals(\"HALF_OPEN\") ? \"trial call \" : \"\";\n            try { op.run(now); }\n            catch (IOException e) {\n                failures++;\n                if (state.equals(\"HALF_OPEN\") || failures >= threshold) { state = \"OPEN\"; openedAt = now; }\n                return trial + \"failed\";\n            }\n            state = \"CLOSED\"; failures = 0;                // success closes and resets\n            return trial + \"ok\";\n        }\n    }\n\n    static void dependency(int now) throws IOException {   // down from t=10 s to t=55 s\n        if (now >= 10 && now < 55) throw new IOException(\"503\");\n    }\n\n    public static void main(String[] args) {\n        CircuitBreaker cb = new CircuitBreaker(3, 30);\n        for (int t = 0; t < 85; t += 5) {\n            String before = cb.state;\n            String result = cb.call(t, Main::dependency);\n            String change = cb.state.equals(before) ? \"\" : \"  \" + before + \" -> \" + cb.state;\n            System.out.printf(\"t=%2ds  %-24s%s%n\", t, result, change);\n        }\n    }\n}", "cpp": "#include <cstdio>\n#include <functional>\n#include <stdexcept>\n#include <string>\n\nclass CircuitBreaker {\npublic:\n    int threshold, cooldown, failures = 0, openedAt = 0;\n    std::string state = \"CLOSED\";\n    CircuitBreaker(int t = 3, int c = 30) : threshold(t), cooldown(c) {}\n\n    std::string call(int now, const std::function<void(int)>& op) {\n        if (state == \"OPEN\") {\n            if (now - openedAt < cooldown) return \"rejected fast (fallback)\";\n            state = \"HALF_OPEN\";                       // cooldown over: allow one trial call\n        }\n        std::string trial = state == \"HALF_OPEN\" ? \"trial call \" : \"\";\n        try { op(now); }\n        catch (const std::runtime_error&) {\n            failures++;\n            if (state == \"HALF_OPEN\" || failures >= threshold) { state = \"OPEN\"; openedAt = now; }\n            return trial + \"failed\";\n        }\n        state = \"CLOSED\"; failures = 0;                // success closes and resets\n        return trial + \"ok\";\n    }\n};\n\nvoid dependency(int now) {                             // down from t=10 s to t=55 s\n    if (now >= 10 && now < 55) throw std::runtime_error(\"503\");\n}\n\nint main() {\n    CircuitBreaker cb;\n    for (int t = 0; t < 85; t += 5) {\n        std::string before = cb.state;\n        std::string result = cb.call(t, dependency);\n        std::string change = cb.state != before ? \"  \" + before + \" -> \" + cb.state : \"\";\n        std::printf(\"t=%2ds  %-24s%s\\n\", t, result.c_str(), change.c_str());\n    }\n}"} });
Object.assign(SD["case-url"], { codeTitle: "Base62 codes", codeNote: "Encode and decode IDs, and see how many codes each length provides.", codeOut: "              0 ->        0  (1 chars)\n             61 ->        Z  (1 chars)\n             62 ->       10  (2 chars)\n            125 ->       21  (2 chars)\n        1000000 ->     4c92  (4 chars)\n     2000000000 ->   2blNmw  (6 chars)\n  3521614606207 ->  ZZZZZZZ  (7 chars)\n5 chars give 916,132,832 codes\n6 chars give 56,800,235,584 codes\n7 chars give 3,521,614,606,208 codes\n8 chars give 218,340,105,584,896 codes", code: {"python": "ALPHABET = \"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\"\nINDEX = {c: i for i, c in enumerate(ALPHABET)}\n\n\ndef encode(n):\n    \"\"\"Base62-encode a non-negative integer.\"\"\"\n    if n == 0:\n        return ALPHABET[0]\n    out = []\n    while n:\n        n, r = divmod(n, 62)\n        out.append(ALPHABET[r])\n    return \"\".join(reversed(out))\n\n\ndef decode(code):\n    n = 0\n    for ch in code:\n        n = n * 62 + INDEX[ch]\n    return n\n\n\nfor n in [0, 61, 62, 125, 1_000_000, 2_000_000_000, 62 ** 7 - 1]:\n    code = encode(n)\n    assert decode(code) == n\n    print(f\"{n:>15} -> {code:>8}  ({len(code)} chars)\")\n\nfor length in range(5, 9):\n    print(f\"{length} chars give {62 ** length:,} codes\")", "javascript": "const ALPHABET = \"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\n// Base62-encode a non-negative integer (BigInt keeps 64-bit IDs exact).\nfunction encode(n) {\n  n = BigInt(n);\n  if (n === 0n) return ALPHABET[0];\n  let out = \"\";\n  while (n > 0n) { out = ALPHABET[Number(n % 62n)] + out; n /= 62n; }\n  return out;\n}\n\nfunction decode(code) {\n  let n = 0n;\n  for (const ch of code) n = n * 62n + BigInt(ALPHABET.indexOf(ch));\n  return n;\n}\n\nfor (const n of [0n, 61n, 62n, 125n, 1000000n, 2000000000n, 62n ** 7n - 1n]) {\n  const code = encode(n);\n  if (decode(code) !== n) throw new Error(\"round trip failed\");\n  console.log(`${String(n).padStart(15)} -> ${code.padStart(8)}  (${code.length} chars)`);\n}\nfor (let length = 5; length <= 8; length++)\n  console.log(`${length} chars give ${(62n ** BigInt(length)).toLocaleString(\"en-US\")} codes`);", "java": "public class Main {\n    static final String ALPHABET = \"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\n    // Base62-encode a non-negative integer.\n    static String encode(long n) {\n        if (n == 0) return String.valueOf(ALPHABET.charAt(0));\n        StringBuilder sb = new StringBuilder();\n        while (n > 0) { sb.append(ALPHABET.charAt((int) (n % 62))); n /= 62; }\n        return sb.reverse().toString();\n    }\n\n    static long decode(String code) {\n        long n = 0;\n        for (char ch : code.toCharArray()) n = n * 62 + ALPHABET.indexOf(ch);\n        return n;\n    }\n\n    public static void main(String[] args) {\n        long max7 = (long) Math.pow(62, 7) - 1;\n        for (long n : new long[]{0, 61, 62, 125, 1_000_000, 2_000_000_000L, max7}) {\n            String code = encode(n);\n            if (decode(code) != n) throw new AssertionError(\"round trip failed\");\n            System.out.printf(\"%15d -> %8s  (%d chars)%n\", n, code, code.length());\n        }\n        long p = 1;\n        for (int i = 0; i < 5; i++) p *= 62;\n        for (int length = 5; length <= 8; length++, p *= 62)\n            System.out.printf(\"%d chars give %,d codes%n\", length, p);\n    }\n}", "cpp": "#include <algorithm>\n#include <cstdint>\n#include <cstdio>\n#include <stdexcept>\n#include <string>\n\nconst std::string ALPHABET = \"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\n// Base62-encode a non-negative integer.\nstd::string encode(uint64_t n) {\n    if (n == 0) return std::string(1, ALPHABET[0]);\n    std::string out;\n    while (n) { out += ALPHABET[n % 62]; n /= 62; }\n    std::reverse(out.begin(), out.end());\n    return out;\n}\n\nuint64_t decode(const std::string& code) {\n    uint64_t n = 0;\n    for (char ch : code) n = n * 62 + ALPHABET.find(ch);\n    return n;\n}\n\nstd::string withCommas(uint64_t v) {\n    std::string s = std::to_string(v);\n    for (int i = (int)s.size() - 3; i > 0; i -= 3) s.insert(i, \",\");\n    return s;\n}\n\nint main() {\n    unsigned long long p7 = 1;\n    for (int i = 0; i < 7; i++) p7 *= 62;\n    for (unsigned long long n : {0ULL, 61ULL, 62ULL, 125ULL, 1000000ULL, 2000000000ULL, p7 - 1}) {\n        std::string code = encode(n);\n        if (decode(code) != n) throw std::logic_error(\"round trip failed\");\n        std::printf(\"%15llu -> %8s  (%zu chars)\\n\", (unsigned long long)n, code.c_str(), code.size());\n    }\n    uint64_t p = 1;\n    for (int i = 0; i < 5; i++) p *= 62;\n    for (int length = 5; length <= 8; length++, p *= 62)\n        std::printf(\"%d chars give %s codes\\n\", length, withCommas(p).c_str());\n}"} });
Object.assign(SD["case-rides"], { codeTitle: "Geohash encoding", codeNote: "Nearby points share long prefixes, which is what makes \u201cfind drivers near me\u201d a prefix lookup.", codeOut: "rider, Union Square SF   9q8yyx1  shared prefix with rider: 7\ndriver 1, 400 m away     9q8yyqx  shared prefix with rider: 5\ndriver 2, Oakland        9q9p1dh  shared prefix with rider: 2\ndriver 3, New York       dr5regw  shared prefix with rider: 0", code: {"python": "BASE32 = \"0123456789bcdefghjkmnpqrstuvwxyz\"\n\n\ndef geohash(lat, lng, precision):\n    \"\"\"Interleave longitude and latitude bits (longitude first), 5 bits per char.\"\"\"\n    lat_lo, lat_hi, lng_lo, lng_hi = -90.0, 90.0, -180.0, 180.0\n    out, bits, ch, even = [], 0, 0, True\n    while len(out) < precision:\n        if even:                               # longitude bit\n            mid = (lng_lo + lng_hi) / 2\n            if lng >= mid:\n                ch, lng_lo = (ch << 1) | 1, mid\n            else:\n                ch, lng_hi = ch << 1, mid\n        else:                                  # latitude bit\n            mid = (lat_lo + lat_hi) / 2\n            if lat >= mid:\n                ch, lat_lo = (ch << 1) | 1, mid\n            else:\n                ch, lat_hi = ch << 1, mid\n        even = not even\n        bits += 1\n        if bits == 5:\n            out.append(BASE32[ch])\n            bits, ch = 0, 0\n    return \"\".join(out)\n\n\ndef common_prefix(a, b):\n    n = 0\n    while n < min(len(a), len(b)) and a[n] == b[n]:\n        n += 1\n    return n\n\n\nplaces = [(\"rider, Union Square SF\", 37.7880, -122.4075),\n          (\"driver 1, 400 m away\", 37.7850, -122.4110),\n          (\"driver 2, Oakland\", 37.8044, -122.2712),\n          (\"driver 3, New York\", 40.7128, -74.0060)]\nrider = geohash(places[0][1], places[0][2], 7)\nfor name, lat, lng in places:\n    g = geohash(lat, lng, 7)\n    print(f\"{name:24} {g}  shared prefix with rider: {common_prefix(rider, g)}\")", "javascript": "const BASE32 = \"0123456789bcdefghjkmnpqrstuvwxyz\";\n\n// Interleave longitude and latitude bits (longitude first), 5 bits per char.\nfunction geohash(lat, lng, precision) {\n  let latLo = -90, latHi = 90, lngLo = -180, lngHi = 180;\n  let out = \"\", bits = 0, ch = 0, even = true;\n  while (out.length < precision) {\n    if (even) {                                // longitude bit\n      const mid = (lngLo + lngHi) / 2;\n      if (lng >= mid) { ch = (ch << 1) | 1; lngLo = mid; } else { ch = ch << 1; lngHi = mid; }\n    } else {                                   // latitude bit\n      const mid = (latLo + latHi) / 2;\n      if (lat >= mid) { ch = (ch << 1) | 1; latLo = mid; } else { ch = ch << 1; latHi = mid; }\n    }\n    even = !even;\n    if (++bits === 5) { out += BASE32[ch]; bits = 0; ch = 0; }\n  }\n  return out;\n}\n\nfunction commonPrefix(a, b) {\n  let n = 0;\n  while (n < Math.min(a.length, b.length) && a[n] === b[n]) n++;\n  return n;\n}\n\nconst places = [[\"rider, Union Square SF\", 37.7880, -122.4075],\n                [\"driver 1, 400 m away\", 37.7850, -122.4110],\n                [\"driver 2, Oakland\", 37.8044, -122.2712],\n                [\"driver 3, New York\", 40.7128, -74.0060]];\nconst rider = geohash(places[0][1], places[0][2], 7);\nfor (const [name, lat, lng] of places) {\n  const g = geohash(lat, lng, 7);\n  console.log(`${name.padEnd(24)} ${g}  shared prefix with rider: ${commonPrefix(rider, g)}`);\n}", "java": "public class Main {\n    static final String BASE32 = \"0123456789bcdefghjkmnpqrstuvwxyz\";\n\n    // Interleave longitude and latitude bits (longitude first), 5 bits per char.\n    static String geohash(double lat, double lng, int precision) {\n        double latLo = -90, latHi = 90, lngLo = -180, lngHi = 180;\n        StringBuilder out = new StringBuilder();\n        int bits = 0, ch = 0; boolean even = true;\n        while (out.length() < precision) {\n            if (even) {                                 // longitude bit\n                double mid = (lngLo + lngHi) / 2;\n                if (lng >= mid) { ch = (ch << 1) | 1; lngLo = mid; } else { ch <<= 1; lngHi = mid; }\n            } else {                                    // latitude bit\n                double mid = (latLo + latHi) / 2;\n                if (lat >= mid) { ch = (ch << 1) | 1; latLo = mid; } else { ch <<= 1; latHi = mid; }\n            }\n            even = !even;\n            if (++bits == 5) { out.append(BASE32.charAt(ch)); bits = 0; ch = 0; }\n        }\n        return out.toString();\n    }\n\n    static int commonPrefix(String a, String b) {\n        int n = 0;\n        while (n < Math.min(a.length(), b.length()) && a.charAt(n) == b.charAt(n)) n++;\n        return n;\n    }\n\n    public static void main(String[] args) {\n        Object[][] places = {{\"rider, Union Square SF\", 37.7880, -122.4075}, {\"driver 1, 400 m away\", 37.7850, -122.4110},\n                             {\"driver 2, Oakland\", 37.8044, -122.2712}, {\"driver 3, New York\", 40.7128, -74.0060}};\n        String rider = geohash((double) places[0][1], (double) places[0][2], 7);\n        for (Object[] p : places) {\n            String g = geohash((double) p[1], (double) p[2], 7);\n            System.out.printf(\"%-24s %s  shared prefix with rider: %d%n\", p[0], g, commonPrefix(rider, g));\n        }\n    }\n}", "cpp": "#include <algorithm>\n#include <cstdio>\n#include <string>\n#include <tuple>\n#include <vector>\n\nconst std::string BASE32 = \"0123456789bcdefghjkmnpqrstuvwxyz\";\n\n// Interleave longitude and latitude bits (longitude first), 5 bits per char.\nstd::string geohash(double lat, double lng, int precision) {\n    double latLo = -90, latHi = 90, lngLo = -180, lngHi = 180;\n    std::string out;\n    int bits = 0, ch = 0; bool even = true;\n    while ((int)out.size() < precision) {\n        if (even) {                                    // longitude bit\n            double mid = (lngLo + lngHi) / 2;\n            if (lng >= mid) { ch = (ch << 1) | 1; lngLo = mid; } else { ch <<= 1; lngHi = mid; }\n        } else {                                       // latitude bit\n            double mid = (latLo + latHi) / 2;\n            if (lat >= mid) { ch = (ch << 1) | 1; latLo = mid; } else { ch <<= 1; latHi = mid; }\n        }\n        even = !even;\n        if (++bits == 5) { out += BASE32[ch]; bits = 0; ch = 0; }\n    }\n    return out;\n}\n\nint commonPrefix(const std::string& a, const std::string& b) {\n    int n = 0;\n    while (n < (int)std::min(a.size(), b.size()) && a[n] == b[n]) n++;\n    return n;\n}\n\nint main() {\n    std::vector<std::tuple<std::string, double, double>> places{\n        {\"rider, Union Square SF\", 37.7880, -122.4075}, {\"driver 1, 400 m away\", 37.7850, -122.4110},\n        {\"driver 2, Oakland\", 37.8044, -122.2712}, {\"driver 3, New York\", 40.7128, -74.0060}};\n    std::string rider = geohash(std::get<1>(places[0]), std::get<2>(places[0]), 7);\n    for (auto& [name, lat, lng] : places) {\n        std::string g = geohash(lat, lng, 7);\n        std::printf(\"%-24s %s  shared prefix with rider: %d\\n\", name.c_str(), g.c_str(), commonPrefix(rider, g));\n    }\n}"} });
